/**
 * The unpaid half of `buy curl`: run the caller's request once, buffered, and
 * read back whether it was a 402 and what the challenge said.
 *
 * Extracted from `curl.ts` so that `buy quote` can ask the same question
 * without the paid half — one probe, two commands. Everything here runs BEFORE
 * any signer is opened, and nothing in this module can sign: it has no access
 * to a key, and the paid retry lives entirely in `curl.ts`.
 */
import { type PaymentRequiredEnvelope } from '@celo/buy-core';
/** What one probe established about the caller's request. */
export type ProbeResult = {
    /** HTTP status of the single transfer the arguments produced. */
    status: number;
    /** curl's own `%{url_effective}` — the URL actually reached. */
    effectiveUrl: string;
    /**
     * The parsed x402 challenge, or undefined when `status` is not 402 or the
     * 402 carried nothing parseable. The caller decides what a missing
     * envelope means: `buy curl` refuses with `invalid_envelope`, `buy quote`
     * does the same, and a non-402 is passed through or refused by each.
     */
    envelope: PaymentRequiredEnvelope | undefined;
    /**
     * Where the challenge was found. Which header the payment goes back in
     * follows from how the challenge arrived, so the paid path needs to know.
     * Undefined when there is no envelope.
     */
    challengeIn: 'body' | 'header' | undefined;
    /** The response body, verbatim; empty when curl wrote none. */
    body: string;
    /** The `-D` dump of the probe's response headers. */
    headersFile: string;
    /** curl's write-out records, one per transfer. Exactly one by the time this returns. */
    records: string[];
    /**
     * `--data-binary @<staged>` when a `dataFile` was given, else empty. The
     * probe already sent these; the caller appends the SAME pair to every
     * further request it makes — the unpaid replay and the paid retry — so the
     * body the server priced is the body it is paid for. The staged file lives
     * in `dir`, so it goes when `cleanup` runs.
     */
    bodyArgs: string[];
    /**
     * The probe's temp directory, still present. The paid retry needs a place
     * for its own header dump; `cleanup` removes it and is idempotent.
     */
    dir: string;
    cleanup: () => void;
};
/**
 * Verbose diagnostics, written as they happen AND collected for the envelope.
 *
 * `-v` diagnostics are prose, and in JSON mode stderr carries JSON — so
 * writing them there raw put unparseable lines IN FRONT of the envelope.
 * They were collected instead and attached to whatever failure is reported.
 * Only to a failure, though: a paid run that SUCCEEDED printed nothing, and
 * JSON mode is on for every piped run, which is how a paid `buy curl` is
 * documented (`| tee`). So each line now also goes out immediately as its
 * own `{"log":"…"}` object — the stream stays one object per line, and the
 * envelope, when there is one, stays the last of them (#133). The buffer
 * survives so the envelope still carries the whole log under `details.log`.
 * Redacted on the way out for the same reason `withDiagnostics` redacts: the
 * probe line echoes the caller's argv verbatim.
 */
export type Diagnostics = {
    log: (msg: string) => void;
    /** Every failure reports the diagnostics the caller asked for. */
    withDiagnostics: (extra: Record<string, unknown>) => Record<string, unknown>;
};
/** What a caller hands the probe. */
export type ProbeOptions = Diagnostics & {
    /**
     * Prefix of the probe's temp directory. Per COMMAND, not shared: the `buy
     * curl` suite proves nothing is left behind by counting `buy-curl-*` in the
     * tmpdir before and after a run, and a `buy quote` test running in parallel
     * under the same prefix made that count race.
     */
    tmpPrefix?: string;
    /**
     * Request body from a file (`-` is stdin), staged BOM-free into the probe's
     * temp directory and sent with the probe. buy's own option, not curl's:
     * the bytes are read and cleaned here rather than by curl's `-d @file`,
     * which forwards a BOM verbatim (celo-org/cpay#178).
     */
    dataFile?: string;
};
export declare function createDiagnostics(verbose: boolean): Diagnostics;
/**
 * Run the caller's curl invocation once, buffered, and read the outcome back.
 *
 * Exits the process itself for the failures that make the result meaningless
 * — curl failed, `--` was passed, more than one transfer happened — because
 * neither command can do anything useful with those, and both used to report
 * them identically. Everything else is returned for the caller to judge.
 */
export declare function probeChallenge(curlArgs: string[], { log, withDiagnostics, tmpPrefix, dataFile }: ProbeOptions): Promise<ProbeResult>;
/**
 * Strip payment and Self attestation values out of text captured from curl.
 *
 * `-v` makes curl echo the headers it SENDS, so both credentials come back on
 * stderr no matter how they were supplied — moving them out of argv does
 * nothing about this. Anything captured from curl and put into a message or
 * into `details` has to go through here first.
 *
 * Matched case-insensitively and in both directions (`>` request, `<`
 * response) because curl prefixes each line and a server may echo the header
 * back. The name is kept so the reader can see something was removed.
 */
export declare function redactSecretHeaders(text: string): string;
/**
 * The caller's curl args with credential VALUES replaced by `<redacted>`, for
 * diagnostics only — never for the argv curl runs with.
 *
 * Mirrors the arity rules of `walkCurlArgs` in `curl.ts` (attached `-HX: y`, separate `-H 'X: y'`,
 * `--header=X: y`, clusters ending in a value-taking letter) so the redacted
 * line still reads as the command that ran. Everything after `--` is data.
 */
export declare function redactSecretArgs(curlArgs: string[]): string[];
/**
 * `-q`, FIRST, on every curl this command runs.
 *
 * curl reads `~/.curlrc` (or `$CURL_HOME`/`$XDG_CONFIG_HOME`) with no argument
 * at all, and a single line there — `stderr = /tmp/x` or `trace-ascii = /tmp/y`
 * — writes the authorization to disk with nothing on the command line for any
 * scan of argv to find. That is the one exposure a denylist provably cannot
 * reach, and `-q` closes all of it.
 *
 * Position matters: verified against curl 8.7.1 that `-q` suppresses the rc
 * file only as the FIRST argument. It does NOT disable an explicit `--config`,
 * which is why that is refused separately.
 *
 * Applied to the probe as well as the paid retry, so a curlrc cannot change the
 * meaning of one and not the other. The cost is that `buy curl` no longer
 * honours a curlrc at all — worth stating plainly rather than having someone
 * discover a header of theirs silently missing.
 */
export declare const NO_CURLRC: string[];
/**
 * Last value of `name` from a curl `-D` dump.
 *
 * LAST, not first: the dump concatenates every response in a redirect chain, and
 * the challenge that matters belongs to the response actually being paid for.
 */
export declare function readResponseHeader(headersPath: string, name: string): string | undefined;
/**
 * The caller's curl args with `-i`/`--include` removed (probe only).
 *
 * A bare letter is dropped from a cluster; a cluster that held only `i`
 * disappears entirely. Value-taking letters end a cluster, so their values
 * are never mistaken for flags.
 */
export declare function withoutInclude(curlArgs: string[]): string[];
/**
 * curl short options that consume a value.
 *
 * Needed to know where a cluster stops being flags: in `-xhttp://k.example` the
 * `k` is part of a URL, not a request for `--insecure`. Scanning past the first
 * value-taking letter is what would turn that into a false refusal.
 */
export declare const SHORT_TAKES_VALUE: ReadonlySet<string>;
/**
 * Every long option the INSTALLED curl consumes a value for, plus the baseline.
 *
 * Asking curl rather than trusting a table means the model cannot drift from
 * the binary it describes — across versions, distributions, or the gap between
 * a developer's machine and CI, which is exactly where the pinned version
 * broke.
 */
export declare function longTakesValue(): ReadonlySet<string>;
export type RunResult = {
    exitCode: number;
    stdout: string;
    stderr: string;
};
/**
 * Spawn curl.
 *
 * EXPORTED for tests, deliberately. Everything that keeps the signed
 * authorization contained lives in here — handing it over fd 3, capturing
 * stderr whenever it is in flight, and redacting what is forwarded — and none
 * of it involves signing. Reaching this through `curlCommand` would need a
 * keychain-backed signer that CI cannot create, so the security property would
 * have had no behavioural test at all; exporting one function is a far smaller
 * concession than a way to inject a private key.
 */
export declare function runCurl(args: string[], opts?: {
    stream?: boolean;
    headerLines?: readonly string[];
}): Promise<RunResult>;
